WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_time NULLS FIRST, id) AS rank_in_group FROM web_events) ranked WHERE rank_in_group = 1), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM deduped), sessions_web_events AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged), enriched AS (SELECT id, session_id, event_type, page, event_time, rank_in_group, is_new_burst, session_no, LEAD(is_new_burst) OVER w_recent AS next_is_new_burst, LAG(is_new_burst) OVER w_recent AS prev_is_new_burst, LAG(session_no) OVER w_recent AS prev_session_no, ROW_NUMBER() OVER w_recent AS event_seq, STDDEV_SAMP(duration_sec) OVER w_ordered AS event_type_stddev_samp_duration_sec FROM sessions_web_events WINDOW w_recent AS (PARTITION BY page, session_id ORDER BY event_time, id), w_ordered AS (PARTITION BY event_type)), enriched_web_events AS (SELECT id, session_id, event_type, event_time, rank_in_group, is_new_burst, prev_is_new_burst, prev_session_no, event_seq, SUM(event_type_stddev_samp_duration_sec) OVER (PARTITION BY event_type ORDER BY session_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_event_type_stddev_samp_duration_sec, LEAD(event_type_stddev_samp_duration_sec, 1) OVER w_ordered AS next_event_type_stddev_samp_duration_sec FROM enriched WINDOW w_ordered AS (PARTITION BY session_id, event_type ORDER BY event_type_stddev_samp_duration_sec, id)), matched_keys AS (SELECT session_id FROM enriched_web_events INTERSECT SELECT session_id FROM web_events WHERE event_type IN ('search', 'add_to_cart', 'page_view')), reconciled AS (SELECT s.* FROM enriched_web_events s JOIN matched_keys k ON s.session_id = k.session_id), with_windows AS (SELECT *, SUM(event_seq) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS event_seq_sum_30d, AVG(prev_is_new_burst) OVER (PARTITION BY session_id, event_type ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS prev_is_new_burst_avg_90d, MAX(event_seq) OVER (PARTITION BY session_id) AS session_id_max_event_seq FROM reconciled) SELECT d.device, a.event_type, COUNT(*) AS rows_total, MIN(a.prev_is_new_burst) AS min_prev_is_new_burst FROM with_windows a LEFT JOIN sessions d ON a.session_id = d.id GROUP BY GROUPING SETS ((d.device, a.event_type), (d.device))
